head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getParameter]<br/>URL 쿼리 문자열(GET 방식) 또는 openPopup() 메소드의 dataObject 에 정의한 값을 반환합니다.",
    "validation" : [
        "param(필수) 파라미터로 값을 가져올 URL 파라미터명 또는 openPopup() 의 dataObject.name 에 정의한 값을 설정할 수 있어야 합니다.",
        "param 에 해당하는 값을 반환해야 합니다.",
        "파라미터가 존재하지 않거나 값이 없으면 빈 문자열('')을 반환해야 합니다.",
        "openPopup() 의 dataObject 를 통해 전달된 값은 원래 타입(JSON 객체 등)으로 반환되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getParameter_onclick = function () {
    var param = par_param.getValue();

    var result = $p.getParameter(param);

    wf_body_bottom.getObj("scwin").setReturnValue("getParameter('" + param + "') : " + (typeof result === "object" ? JSON.stringify(result) : "'" + result + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);
}



scwin.btn_navigateWithParam_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("$p.url 로 파라미터 전달하여 이동합니다.");

    $p.url("/sample/p/p_M_getParameter_1.xml", {
        spa: false,
        param: {"userID": "1234", "name": "WebSquare"}
    });
}



scwin.btn_openPopupWithData_onclick = function () {
    var options = {
        id: "getParameter_popup",
        type: "wframePopup",
        width: "600px",
        height: "350px",
        top: "100px",
        left: "100px",
        popupName: "getParameter 테스트 팝업",
        modal: false,
        dataObject: {
            type: "json",
            name: "rowObj",
            data: {name: "WebSquare", version: "5.0"}
        }
    };

    $p.openPopup("/sample/common_link/p_getParameter_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (dataObject.name: rowObj)");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 getParameter('rowObj') 결과를 확인하세요.");
}
